// Turns one app event into a list of WhatsApp messages, each with a delay in hours.
const b = $input.first().json.body || $input.first().json;
const out = [];
const wa = (n) => 'whatsapp:' + String(n).replace(/[^\d+]/g, '').replace(/^(\d{10})$/, '+91$1');

if (b.event === 'matched') {
  out.push({ to: wa(b.parent.phone), body: b.parent_message + '\n\nSlots: ' + b.slot_options.join(' | ') + '\nReply with the one you prefer, or confirm on the page.', delayHours: 0 });
  out.push({ to: wa(b.volunteer.phone), body: 'A parent would like a short, honest chat with you.\n\n' + b.brief_volunteer + '\n\nYou are not asked to promote NIAT. Share what you really experienced.', delayHours: 0 });
}
if (b.event === 'booked') {
  out.push({ to: wa(b.parent.phone), body: 'Your call is booked for ' + b.slot + '. We will remind you before it starts.', delayHours: 0 });
  out.push({ to: wa(b.volunteer.phone), body: 'The call is booked for ' + b.slot + '. Thank you for helping another parent.', delayHours: 0 });
  out.push({ to: wa(b.parent.phone), body: 'How did your call go? Two minutes, three questions: ' + b.feedback_url, delayHours: 24 });
}
return out.map(m => ({ json: m }));
